import{_ as d,o as e,c as a,ak as r}from"./chunks/framework.DKi5cyCJ.js";const P=JSON.parse('{"title":"SPI 总线","description":"CPOL/CPHA 四种模式、片选、哑字节与模式错一位的现象","frontmatter":{"title":"SPI 总线","description":"CPOL/CPHA 四种模式、片选、哑字节与模式错一位的现象","date":"2026-10-20T00:00:00.000Z"},"headers":[],"relativePath":"pages/blog/2026-10-20-SPI总线.md","filePath":"pages/blog/2026-10-20-SPI总线.md"}'),o={name:"pages/blog/2026-10-20-SPI总线.md"};function p(i,t,l,s,h,n){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="spi-四种模式与片选" tabindex="-1">SPI：四种模式与片选 <a class="header-anchor" href="#spi-四种模式与片选" aria-label="Permalink to &quot;SPI：四种模式与片选&quot;">​</a></h1><blockquote><p>系列目录：<a href="/pages/blog/2026-10-20-嵌入式驱动面试手册.html">嵌入式驱动面试手册</a> · <a href="/demos/spi-timing.html" target="_blank">时序动画</a></p></blockquote><div class="blog-demo-frame"><iframe src="/demos/spi-timing.html?embed=1" title="SPI 时序动态演示" loading="lazy"></iframe></div><p>SPI 是主从同步总线，通常全双工。线是 SCLK、MOSI、MISO、CS。没有起始位、地址和 ACK。片选一般低有效，它本身就是“这台从机被选中”。多个从机共用时钟和数据时，每台要有独立片选，没被选中的从机必须把 MISO 释放成高阻。</p><p>CPOL 是空闲电平。CPHA = 0 在第一个时钟沿采样，CPHA = 1 在第二个沿采样。</p><table tabindex="0"><thead><tr><th>模式</th><th>CPOL</th><th>CPHA</th><th>空闲</th><th>采样沿</th></tr></thead><tbody><tr><td>0</td><td>0</td><td>0</td><td>低</td><td>上升沿</td></tr><tr><td>1</td><td>0</td><td>1</td><td>低</td><td>下降沿</td></tr><tr><td>2</td><td>1</td><td>0</td><td>高</td><td>下降沿</td></tr><tr><td>3</td><td>1</td><td>1</td><td>高</td><td>上升沿</td></tr></tbody></table><p>模式 0 和 3 最常见，都是上升沿采样，差别是空闲电平。模式差 1 时，读数常常整体错 1 位。MSB 还是 LSB 先发是另一项配置。</p><h2 id="读寄存器" tabindex="-1">读寄存器 <a class="header-anchor" href="#读寄存器" aria-label="Permalink to &quot;读寄存器&quot;">​</a></h2><p>很多传感器第一字节是命令，这一拍的 MISO 无效。主机必须再发一个哑字节，才能把寄存器值移出来。命令里的“读”标志以芯片手册为准，<code>0x80</code> 不是 SPI 标准。</p><p>传输期间片选必须保持有效。硬件 NSS 若在字节之间把片选抬高，从机状态机会复位，表现为单字节对、连续读就漂。</p><p>即使只想发送，也要把接收寄存器读走，否则溢出后后续字节错位。结束前要等忙标志清除，只看发送缓冲空就拉高片选，最后一位可能还在移位。</p><p>STM32 上对数据寄存器做 8 位访问。16 位写会一次装入两个字节。</p><p><a href="/pages/blog/2026-10-20-嵌入式驱动面试手册.html">返回目录</a></p>',13)])])}const _=d(o,[["render",p]]);export{P as __pageData,_ as default};
